import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mx_noise_float, uniform, mix, vec3, time, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Root group
  const group = new THREE.Group();
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.rotation);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(textMesh);

    // Clean up primitive timelines
    if (primitiveResults.parallax) primitiveResults.parallax.cleanup();
    if (primitiveResults.depthRotate) primitiveResults.depthRotate.cleanup();

    // Dispose materials and geometries
    if (planeMesh.material) planeMesh.material.dispose();
    if (planeMesh.geometry) planeMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
  };

  const primitiveResults = {};

  // Load textures in parallel
  let colorTexture = null;
  let depthTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      colorTexture = tex;
      colorTexture.needsUpdate = true;
      if (planeMesh.material) {
        planeMesh.material.colorMap = colorTexture;
        planeMesh.material.needsUpdate = true;
      }
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTexture = tex;
      if (planeMesh.material) {
        planeMesh.material.displacementMap = depthTexture;
        planeMesh.material.needsUpdate = true;
      }
    });
  }

  // Create tessellated plane geometry (64x64 segments for displacement)
  const geometry = new THREE.PlaneGeometry(4, 2.5, 64, 64);

  // TSL displacement setup
  const displacementScale = uniform(0.15);
  const displacementBias = uniform(0.0);

  const displacementNode = mix(
    displacementBias,
    displacementScale,
    positionLocal.z.div(2).add(0.5)
  );

  // Create material with TSL nodes
  const material = new MeshStandardNodeMaterial({
    color: 0xffffff,
    metalness: 0.35,
    roughness: 0.6,
    clearcoat: 0.18,
  });

  // Set displacement via TSL
  material.displacementScale = 0.15;
  material.displacementMap = depthTexture;
  material.map = colorTexture;

  const planeMesh = new THREE.Mesh(geometry, material);
  planeMesh.castShadow = true;
  planeMesh.receiveShadow = true;
  group.add(planeMesh);

  // Create a subtle attribution text element (positioned below the image)
  // Using a placeholder for the quote attribution
  const textMesh = ctx.fontAtlas.createText('Nova Atelier Client', {
    fontSize: 32,
    color: '#e8ecf2',
    align: 'center',
  });
  textMesh.position.set(0, -1.4, 0.1);
  textMesh.scale.set(0.005, 0.005, 1);
  group.add(textMesh);

  // Apply cinematic primitives
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (primitive.name === 'parallax-scroll') {
        primitiveResults.parallax = ctx.primitives['parallax-scroll'](
          group,
          primitive.params || { intensity: 0.4 }
        );
      } else if (primitive.name === 'depth-rotate') {
        primitiveResults.depthRotate = ctx.primitives['depth-rotate'](
          group,
          primitive.params || { maxDeg: 8 }
        );
      }
    }
  }

  // Entrance animation: rise-in + fade
  gsap.fromTo(
    group.position,
    { y: group.position.y + 0.15 },
    { y: group.position.y, duration: 0.7, ease: 'power3.out' }
  );

  gsap.fromTo(
    group,
    { opacity: 0 },
    { opacity: 1, duration: 0.5, ease: 'power2.out' }
  );

  // Hover handler: subtle rise
  group.userData.handlers.hover = () => {
    gsap.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.4,
      ease: 'power2.out',
    });
  };

  group.userData.handlers.unhover = () => {
    gsap.to(group.position, {
      y: group.position.y,
      duration: 0.6,
      ease: 'power4.out',
    });
  };

  // Click handler: emit navigation event
  group.userData.handlers.click = () => {
    ctx.emit('navigate', { to: 'hub-home', action: 'select' });
  };

  return group;
}
